def import_stock_valuation(apps, schema_editor):
    StockValuationItem = apps.get_model('projects', 'StockValuationItem')
    StockValuationItem.objects.all().delete()  # clean re-import if this runs more than once
    to_create = []
    for item in BOARD_ITEMS:
        to_create.append(StockValuationItem(
            description=item['desc'], category='board_stock',
            date_changed=item['date_changed'][:60], po_reference=item['po_ref'][:100],
            quantity=item['qty'], cost_gbp=item['cost_gbp'], cost_eur=item['cost_eur'],
            cost_cad=item['cost_cad'], cost_usd=item['cost_usd'], total_gbp=item['total_gbp'],
        ))
    for item in NON_STOCK_ITEMS:
        to_create.append(StockValuationItem(
            description=item['desc'], category='non_stock',
            total_gbp=item['total_gbp'],
            cost_eur=item['total_eur'],  # non-stock rows store the raw total directly, not qty x unit cost
        ))
    StockValuationItem.objects.bulk_create(to_create)


